def _parse_utc_z_query(raw: str, field: str) -> str:
    """校验并返回查询参数中的 UTC 秒精度 Z 时间串。

    仅接受形如 YYYY-MM-DDTHH:MM:SSZ 的合法时刻（拒绝空白、毫秒、时区
    偏移、缺 Z、未补零、非法月/日/时分秒与 Unicode 数字），返回原文
    （定宽 Z 串按字典序比较与时间先后一致）。
    """
