def _verify_credential_status_receipt_item(
    self,
    tenant: str,
    receipt: Any,
    signature: str,
    nonce: str,
) -> Optional[str]:
    # 凭证状态同步回执验真（只读）：按序返回失败原因（回执非法
    # -> nonce错误 -> 锚点不可用 -> 签名格式错误 -> 签名校验
    # 失败），成功返回 None。不查询当前同步状态、不写状态、
    # 历史或审计。
    receipt_fields = (
        "issuer_did",
        "credential_id",
        "status",
        "reason",
        "updated_at",
        "issuer_key_version",
        "verifier_did",
        "verifier_key_version",
        "nonce",
    )
    # 阶段一：回执结构——恰为九键对象，字段类型与状态取值沿用
    # /v1/trust/credential-status/receipt 公开协议；提交键序不
    # 影响验真（验签前规范化）。
    if not isinstance(receipt, dict) or set(receipt) != set(
        receipt_fields
    ):
        return "回执非法"
    for field in (
        "issuer_did",
        "credential_id",
        "status",
        "updated_at",
        "verifier_did",
    ):
        if not isinstance(receipt[field], str) or not receipt[field]:
            return "回执非法"
    if receipt["status"] not in (
        "active",
        "revoked",
        "unknown",
        "suspended",
    ):
        return "回执非法"
    updated_at = receipt["updated_at"]
    if not _UTC_Z_QUERY_RE.match(updated_at):
        return "回执非法"
    try:
        datetime.strptime(
            updated_at, "%Y-%m-%dT%H:%M:%SZ"
        ).replace(tzinfo=timezone.utc)
    except (ValueError, TypeError):
        return "回执非法"
    # reason：同步记录无值时为 null（suspended 在同步协议下必有
    # 裁剪后 1..256 码点原因，故 null 不可能）；其余为非空字符
    # 串（非 suspended 状态按原文保存，不设长度上限）。
    reason_value = receipt["reason"]
    if reason_value is None:
        if receipt["status"] == "suspended":
            return "回执非法"
    else:
        if not isinstance(reason_value, str) or not reason_value:
            return "回执非法"
        if receipt["status"] == "suspended" and not (
            1 <= len(reason_value.strip()) <= 256
        ):
            return "回执非法"
    for field in ("issuer_key_version", "verifier_key_version"):
        version = receipt[field]
        if (
            not isinstance(version, int)
            or isinstance(version, bool)
            or version < 1
        ):
            return "回执非法"
    receipt_nonce = receipt["nonce"]
    if (
        not isinstance(receipt_nonce, str)
        or not 1 <= len(receipt_nonce) <= 256
    ):
        return "回执非法"

    # 阶段二：内外两处 nonce 相等。
    if receipt_nonce != nonce:
        return "nonce错误"

    # 阶段三：本租户同 verifier_did/版本且含 status 用途的
    # active 锚点。不查询当前同步状态。
    public_pem = store.get_active_trust_anchor_public_key(
        tenant,
        receipt["verifier_did"],
        receipt["verifier_key_version"],
        required_use="status",
    )
    if public_pem is None:
        return "锚点不可用"
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return "锚点不可用"

    # 阶段四：签名格式（ES256 64 字节裸 R||S 无填充 base64url）。
    try:
        crypto.validate_signature_format_strict(signature)
    except crypto.MalformedSignature:
        return "签名格式错误"

